/**
 * Restore original sensitive data into masked text using the mapping generated by maskPII.
 */
export function unmaskPII(maskedText: string, map: Record<string, string>): string {
  if (!maskedText || !map || Object.keys(map).length === 0) {
    return maskedText
  }

  let restored = maskedText
  // Sort placeholders by length descending to prevent substring collisions
  const placeholders = Object.keys(map).sort((a, b) => b.length - a.length)

  for (const placeholder of placeholders) {
    const originalValue = map[placeholder]
    if (originalValue !== undefined) {
      // Global replacement of placeholder
      restored = restored.split(placeholder).join(originalValue)
    }
  }

  return restored
}
